246	static void test_insert_ascending_triggers_rr_rotation(void) {
247	    /* a < b < c inserted in ascending order forces the RR straight-line case
248	     * at the root: c (red) under b (red) under a (root, black), uncle NIL.
249	     * A left rotation at a must promote b to root. If the rotation forgets to
250	     * update t->root, rb_find would search from the stale (demoted) root and
251	     * silently miss keys — the stale-root regression. */
252	    rbtree_t *t = rb_create(NULL);
253	    int va = 1, vb = 2, vc = 3;
254	    check(rb_insert(t, "a", &va) == 0, "insert a");
255	    check(rb_insert(t, "b", &vb) == 0, "insert b");
256	    check(rb_insert(t, "c", &vc) == 0, "insert c (triggers RR rotation at root)");
257	    check(rb_find(t, "a") == &va, "find a after RR rotation");
258	    check(rb_find(t, "b") == &vb, "find b after RR rotation");
259	    check(rb_find(t, "c") == &vc, "find c after RR rotation");
260	    check(rb_size(t) == 3, "size is 3 after RR-triggering inserts");
261	    check(rb_validate(t) == 0, "validate passes after RR rotation");
262	    struct order_ctx ctx = { .count = 0 };
263	    rb_foreach(t, collect_key, &ctx);
264	    check(ctx.count == 3 && strcmp(ctx.keys[0], "a") == 0 &&
265	          strcmp(ctx.keys[1], "b") == 0 && strcmp(ctx.keys[2], "c") == 0,
266	          "foreach still in order after RR rotation");
267	    rb_destroy(t);
268	}
