386	/* ---- rb_delete: table-driven cases ----
387	 * Each case builds a tree via a fixed insertion sequence (chosen so the
388	 * insertion fixup produces the exact structural situation named), deletes
389	 * one key, then asserts rb_delete's return code, rb_size, rb_validate, that
390	 * the deleted key is gone, and that every surviving key is still findable.
391	 * Mirrored cases are literal left/right mirrors of their sibling case
392	 * (mirrored keys), per NOTES.md's decision tree and the spec's explicit
393	 * call-out that the mirror is "the half people forget."
394	 */
395	struct delete_case {
396	    const char *name;
397	    const char *insert_keys[TEST_MAX_KEYS];
398	    int         insert_count;
399	    const char *delete_key;
400	};
401	
402	static const struct delete_case delete_cases[] = {
403	    /* Red leaf: with keys b,a,c inserted, a and c end up red leaf children
404	     * of black root b. Deleting a red leaf needs no fixup at all. */
405	    { "delete red leaf", { "b", "a", "c" }, 3, "a" },
406	    { "delete red leaf (mirror)", { "b", "a", "c" }, 3, "c" },
407	
408	    /* Black leaf with red sibling (verified against an instrumented scratch
409	     * build that dumps real node colors -- an earlier candidate sequence
410	     * looked right by hand-simulation but actually produced a BLACK sibling
411	     * with red nephews, i.e. Case 4, not this Case 5):
412	     * c,b,d,f,g,l,n inserted, then delete b: b ends up a black leaf whose
413	     * sibling f is genuinely RED (f's children d is a black leaf, l is
414	     * black with red children g,n). Deleting b forces Case 5 (red sibling
415	     * rotated up over the parent, colors swapped, then the loop re-examines
416	     * the new -- now black -- sibling). */
417	    { "delete black leaf with red sibling",
418	      { "c", "b", "d", "f", "g", "l", "n" }, 7, "b" },
419	    /* Mirror: p,n,l,k,c,i,e inserted, then delete p: p is a black leaf
420	     * whose sibling k is RED, but on the LEFT this time, forcing the
421	     * mirrored (right) rotation direction. */
422	    { "delete black leaf with red sibling (mirror)",
423	      { "p", "n", "l", "k", "c", "i", "e" }, 7, "p" },
424	
425	    /* Node with two children: root has two children; delete the root itself
426	     * so the successor-splice path is exercised on the two-children case
427	     * generally (also doubles as the "root deletion" requirement). */
428	    { "delete node with two children (root)",
429	      { "d", "b", "f", "a", "c", "e", "g" }, 7, "d" },
430	    { "delete node with two children (non-root)",
431	      { "d", "b", "f", "a", "c", "e", "g" }, 7, "f" },
432	
433	    /* Root deletion, single node: the only node in the tree is the root. */
434	    { "delete root (single node tree)", { "only" }, 1, "only" },
435	
436	    /* delete_fixup Case 4, far nephew red directly (no near-red conversion
437	     * rotation needed): d,b,f,a,c,e,g,h inserted, then delete e. e is a black
438	     * leaf; parent f is red; sibling g is black with g->right=h red (far
439	     * nephew) and g->left=NULL (near nephew, black). is_black(sib->right) is
440	     * false, so the code skips the rotate_right(sib) conversion at
441	     * rbtree.c:203-208 and goes straight to the terminal recolor+rotate_left.
442	     * Verified against a real build (not hand-simulated only): rb_delete
443	     * returns 0, rb_validate passes, and the resulting shape/colors (f
444	     * black, g promoted red, h recolored black) match predicting the
445	     * terminal block by hand. */
446	    { "delete Case 4 (sibling black, far nephew red, direct)",
447	      { "d", "b", "f", "a", "c", "e", "g", "h" }, 8, "e" },
448	    /* Mirror: e,g,c,h,f,d,b,a is the exact structural mirror of the above
449	     * (built by mapping each key to its mirrored in-order role, then
450	     * verifying the pre-delete tree's shape/colors are the left-right
451	     * mirror before deleting) -- delete d hits the x==parent->right branch,
452	     * sib=b, far nephew=a red, same direct-terminal path via rotate_right. */
453	    { "delete Case 4 (sibling black, far nephew red, direct, mirror)",
454	      { "e", "g", "c", "h", "f", "d", "b", "a" }, 8, "d" },
455	
456	    /* delete_fixup Case 4, near nephew red / far nephew black -- forces the
457	     * rotate_right(t, sib) conversion at rbtree.c:203-208 before the same
458	     * terminal block Case-4-direct already exercises. d,b,f,a,c,e,g,fz
459	     * inserted (key "fz" sorts between f and g under strcmp), then delete e.
460	     * e is a black leaf; parent f is red; sibling g is black with
461	     * g->left=fz red (near nephew) and g->right=NULL (far nephew, black).
462	     * is_black(sib->right) is true, so the conversion rotation fires (fz
463	     * recolored black, g recolored red, rotate_right(g), sib reassigned to
464	     * fz) before the terminal recolor+rotate_left. Verified against a real
465	     * build: rb_delete returns 0, rb_validate passes, and the resulting
466	     * shape (fz promoted red, f and g as its black children) matches
467	     * predicting the conversion-then-terminal sequence by hand. */
468	    { "delete Case 4 (sibling black, near nephew red, conversion)",
469	      { "d", "b", "f", "a", "c", "e", "g", "fz" }, 8, "e" },
470	    /* Mirror: e,g,c,h,f,d,a,b is the structural mirror (mapping
471	     * f<->c, fz<->b, g<->a, e<->d, d<->e, c<->f, b<->g, a<->h), verified
472	     * node-by-node against the left case's shape before deleting -- delete
473	     * d hits the x==parent->right branch, sib=a, near nephew=b red (far
474	     * nephew NULL), forcing the mirrored rotate_left(t, sib) conversion. */
475	    { "delete Case 4 (sibling black, near nephew red, conversion, mirror)",
476	      { "e", "g", "c", "h", "f", "d", "a", "b" }, 8, "d" },
477	
478	    /* delete_fixup Case 3a: both nephews black, PARENT RED -- terminal (no
479	     * climb). Exhaustively brute-forced every insertion permutation of
480	     * n=4..8 sequential keys against the real rb_insert looking for a
481	     * non-root red node with two black children whose own children are
482	     * black; zero matches exist below n=8 (a red-uncle recolor producing
483	     * this shape needs a same-black-height sibling subtree under the root,
484	     * which needs real depth). a,b,c,d,e,f,g,h ascending, then delete a:
485	     * a is a black leaf; parent b is red; sibling c is black with both
486	     * children NIL (nephews). delete_fixup's x==parent->left branch skips
487	     * Case 5 (sib not red) and lands in the both-nephews-black check
488	     * (rbtree.c:198), which recolors c red and reassigns x=b, parent=d --
489	     * then the while guard's is_black(x) sees x=b is RED and exits the loop
490	     * immediately (no second iteration/climb), so the post-loop catch-all
491	     * at rbtree.c:243 paints b black. Two recolors, zero rotations, debt
492	     * absorbed in one step because b had "room" (was red) to become black.
493	     * Verified against a real build: rb_delete returns 0, rb_validate
494	     * passes, and b(B)/c(R) with f's subtree completely untouched matches
495	     * the hand-traced recolor exactly. */
496	    { "delete Case 3a (sibling black, both nephews black, parent red)",
497	      { "a", "b", "c", "d", "e", "f", "g", "h" }, 8, "a" },
498	    /* Mirror: h,g,f,e,d,c,b,a (the mirror of a fully-ascending sequence is
499	     * the fully-descending one) -- delete h hits the x==parent->right
500	     * branch, sib=f (both children NIL), parent g red; same terminal
501	     * recolor-absorb, verified as g's exact structural mirror before and
502	     * after delete. */
503	    { "delete Case 3a (sibling black, both nephews black, parent red, mirror)",
504	      { "h", "g", "f", "e", "d", "c", "b", "a" }, 8, "h" },
