556	    /* Black node with exactly one (red) child: b inserted then a inserted
557	     * descending leaves b black with a single red left child a (no fixup
558	     * needed for 2 nodes -- b stays black, a is red). Deleting b splices
559	     * a into its place. */
560	    { "delete black node with one red child (left)",
561	      { "b", "a" }, 2, "b" },
