566	static void run_delete_case(const struct delete_case *c) {
567	    rbtree_t *t = rb_create(NULL);
568	    int values[TEST_MAX_KEYS] = {0};
569	    char msg[256];
570	
571	    for (int i = 0; i < c->insert_count; i++) {
572	        snprintf(msg, sizeof msg, "[%s] insert %s", c->name, c->insert_keys[i]);
573	        check(rb_insert(t, c->insert_keys[i], &values[i]) == 0, msg);
574	    }
