576	    snprintf(msg, sizeof msg, "[%s] rb_delete(%s) returns 0", c->name, c->delete_key);
577	    check(rb_delete(t, c->delete_key) == 0, msg);
578	
579	    snprintf(msg, sizeof msg, "[%s] size decremented after delete", c->name);
580	    check(rb_size(t) == (size_t)(c->insert_count - 1), msg);
581	
582	    snprintf(msg, sizeof msg, "[%s] rb_validate passes after delete", c->name);
583	    check(rb_validate(t) == 0, msg);
584	
