586	    check(rb_find(t, c->delete_key) == NULL, msg);
587	
588	    for (int i = 0; i < c->insert_count; i++) {
589	        if (strcmp(c->insert_keys[i], c->delete_key) == 0) continue;
590	        snprintf(msg, sizeof msg, "[%s] surviving key %s still found", c->name, c->insert_keys[i]);
591	        check(rb_find(t, c->insert_keys[i]) != NULL, msg);
592	    }
593	
594	    rb_destroy(t);
595	}
